    "tc.name.open_order": "Lockere Formation",
    "tc.name.iron_line": "Letztes Aufgebot",
    "tc.desc.iron_line": "Stellst du alle Helden in die vordere Reihe, überlebt der erste Verbündete, der tödlichen Schaden erleidet, mit 1 LP. Einmal pro Kampf.",
    "tc.name.pursuit": "Verfolgungsformation",
